    ('rYBAIbGVDVg', $seg$[{"start_seconds":0,"end_seconds":108,"summary":"Overview of identifying and graphing linear systems and inequalities, including finding solutions and shaded regions.","sub_skills":[],"clusters":[{"id":"CL.0176","evidence":"The instructor states that the solution to a system of inequalities is where both regions are shaded."},{"id":"CL.0177","evidence":"The instructor states that the solution to a linear system is the intersection point of the lines."}]},{"start_seconds":108,"end_seconds":337,"summary":"Worked example of identifying the system of linear equations that matches a given graph using intercepts and slopes.","sub_skills":[{"id":"LE2.4","evidence":"The solution involves finding the slope and y-intercept of each line from the graph and matching them to the equations."},{"id":"SYS.5","evidence":"The question asks which system of linear equations is represented by the lines shown in the graph."}],"clusters":[{"id":"CL.0024","evidence":"The instructor computes the slope of the lines by counting the rise and run on the grid."},{"id":"CL.0072","evidence":"The instructor reads the y-intercepts (0,6) and (0,4) directly from the graph."},{"id":"CL.0080","evidence":"The instructor rewrites the standard form equations from the choices into slope-intercept form."},{"id":"CL.0160","evidence":"The instructor reads the slope and y-intercept from the rewritten slope-intercept equations."}]},{"start_seconds":337,"end_seconds":378,"summary":"Using Desmos to graph the system of equations from the choices and match it to the given graph.","sub_skills":[{"id":"SYS.5","evidence":"The segment shows how to graph the system of equations in Desmos to find the matching graph."}],"clusters":[{"id":"CL.0225","evidence":"The instructor types the system of equations into Desmos, graphs them, and clicks on the intercepts and intersection point."}]}]$seg$::jsonb),
    ('sfddPwRkLrg', $seg$[{"start_seconds":0,"end_seconds":140,"summary":"Learn to use vertical angles and linear pairs/triples to find unknown angle measures, including using algebra and Desmos.","sub_skills":[],"clusters":[{"id":"CL.0047","evidence":"The instructor isolates the variable to solve the linear equation for the angle measure."},{"id":"CL.0094","evidence":"The instructor substitutes x = 4 back into the angle expressions to find their measures."},{"id":"CL.0112","evidence":"The instructor explains that linear pairs and triples lie on a straight line and sum to 180 degrees."},{"id":"CL.0179","evidence":"The instructor identifies vertical angles as being opposite each other and equal."},{"id":"CL.0220","evidence":"The instructor uses Desmos to graph the equation 19x - 3 = 7x + 45 and find the x-intercept at x = 4."}]}]$seg$::jsonb),
    ('synCZPyaMDY', $seg$[{"start_seconds":0,"end_seconds":60,"summary":"Introduction to the difference of squares formula and basic factoring examples.","sub_skills":[{"id":"EE.3","evidence":"Factoring quadratic and higher-degree binomials using the difference of squares formula."}],"clusters":[{"id":"CL.0164","evidence":"Identifying a minus sign between two perfect squares to apply the formula."}]},{"start_seconds":60,"end_seconds":104,"summary":"Factoring an expression by first pulling out a greatest common factor and then applying difference of squares twice.","sub_skills":[{"id":"EE.3","evidence":"Factoring a polynomial by pulling out a GCF and applying the difference of squares repeatedly."}],"clusters":[{"id":"CL.0039","evidence":"Factoring out the greatest common factor x from the expression."},{"id":"CL.0164","evidence":"Recognizing and factoring the difference of squares twice."}]},{"start_seconds":104,"end_seconds":144,"summary":"Simplifying a rational expression by factoring a non-perfect square difference of squares using square roots.","sub_skills":[{"id":"EE.3","evidence":"Factoring x^2 - 41 as a difference of squares using square roots."},{"id":"EE.5","evidence":"Simplifying a rational expression by factoring the numerator and canceling a common factor with the denominator."}],"clusters":[{"id":"CL.0008","evidence":"Canceling the common factor x + sqrt(41) from the numerator and denominator."},{"id":"CL.0164","evidence":"Factoring x^2 - 41 as a difference of squares."}]}]$seg$::jsonb),
    ('tGQz6D-D4os', $seg$[{"start_seconds":0,"end_seconds":129,"summary":"Overview of sampling methods, including random and representative sampling, and the rules for generalizing study results.","sub_skills":[],"clusters":[{"id":"CL.0131","evidence":"The instructor defines a random sample as one where every member has an equal chance of selection."},{"id":"CL.0157","evidence":"The instructor explains that you can only generalize to the population you sampled from."}]}]$seg$::jsonb),
    ('wkLGsN6zeK8', $seg$[{"start_seconds":57,"end_seconds":191,"summary":"How to find the roots of a quadratic equation using factoring, the quadratic formula, or sum/product formulas.","sub_skills":[],"clusters":[{"id":"CL.0007","evidence":"The instructor applies the quadratic formula to solve 3x^2 - 2x - 3 = 0."},{"id":"CL.0037","evidence":"The instructor factors the quadratic expression x^2 + 9x - 10."},{"id":"CL.0120","evidence":"The instructor uses the sum and product formulas to find the product of the roots of x^2 - 4x + 8."},{"id":"CL.0122","evidence":"The instructor sets the factored terms equal to zero to find the roots."}]},{"start_seconds":191,"end_seconds":380,"summary":"How to find the vertex of a parabola using either the vertex formula or the midpoint of its zeros.","sub_skills":[],"clusters":[{"id":"CL.0043","evidence":"The instructor uses the formula h = -b/(2a) to find the x-coordinate of the vertex."},{"id":"CL.0210","evidence":"The instructor explains that the vertex is always located in the middle of the two roots."}]},{"start_seconds":380,"end_seconds":535,"summary":"How to identify equivalent quadratic forms (factored form and vertex form) that display specific features of a parabola.","sub_skills":[],"clusters":[{"id":"CL.0159","evidence":"The instructor selects the equivalent form that displays the x-intercepts or the minimum value as constants."}]},{"start_seconds":535,"end_seconds":717,"summary":"How to use the discriminant to find the number of x-intercepts or intersections of a parabola.","sub_skills":[],"clusters":[{"id":"CL.0025","evidence":"The instructor evaluates the discriminant b^2 - 4ac."},{"id":"CL.0095","evidence":"The instructor substitutes the line equation into the parabola equation to combine them."}]}]$seg$::jsonb),
    ('x16CyJHMdno', $seg$[{"start_seconds":0,"end_seconds":24,"summary":"Introduction to the Radius Tangent Theorem, explaining that the radius and tangent line are perpendicular.","sub_skills":[],"clusters":[{"id":"CL.0208","evidence":"The instructor explains that the radius and tangent line are perpendicular at the point of tangency."}]},{"start_seconds":24,"end_seconds":60,"summary":"Finding a circle's area using the Radius Tangent Theorem and the Pythagorean theorem.","sub_skills":[{"id":"AV.2","evidence":"The final step requires calculating the area of the circle using the radius."},{"id":"CIR4","evidence":"The question involves a tangent segment forming a right triangle with the radius."},{"id":"RTT1","evidence":"The Pythagorean theorem is used to find the missing radius of the right triangle."}],"clusters":[{"id":"CL.0118","evidence":"The instructor uses the Pythagorean theorem to calculate the length of the radius."},{"id":"CL.0119","evidence":"The instructor uses the circle area formula to find the final answer."},{"id":"CL.0184","evidence":"The instructor recognizes a right triangle formed by the radius, tangent segment, and hypotenuse."},{"id":"CL.0208","evidence":"The instructor identifies that the tangent line segment forms a right angle with the radius."}]},{"start_seconds":60,"end_seconds":171,"summary":"Finding the equation of a tangent line and identifying a point on it using Desmos.","sub_skills":[{"id":"CIR2","evidence":"The problem requires finding the equation of a line tangent to a circle at a specific point."},{"id":"LE2.4","evidence":"The student must find the equation of a line from its slope and a point."},{"id":"LE2.5","evidence":"The student must find the slope of a perpendicular tangent line from the radial slope."}],"clusters":[{"id":"CL.0024","evidence":"The instructor calculates the slope of the radius using the coordinates of the center and the point of tangency."},{"id":"CL.0116","evidence":"The instructor takes the negative recipro