    ('z2Lpcp2enXY', $seg$[{"start_seconds":0,"end_seconds":53,"summary":"Learn how to factor a four-term polynomial by grouping them into pairs and factoring out their greatest common factors.","sub_skills":[{"id":"EE.3","evidence":"The segment teaches how to factor a four-term polynomial into a product of binomials."}],"clusters":[{"id":"CL.0038","evidence":"The instructor groups the terms into pairs to factor them."},{"id":"CL.0039","evidence":"The instructor factors out the GCF from each of the two groups."}]},{"start_seconds":53,"end_seconds":99,"summary":"Learn how to factor by grouping when you must factor out -1 to get a repeating binomial, then factor DOTS.","sub_skills":[{"id":"EE.3","evidence":"The segment teaches how to factor a polynomial by grouping and then factoring a difference of squares."}],"clusters":[{"id":"CL.0038","evidence":"The instructor groups the terms into pairs to factor them."},{"id":"CL.0039","evidence":"The instructor factors out the GCF from the first group."},{"id":"CL.0164","evidence":"The instructor recognizes x^2 - 1 as a difference of squares and factors it."}]},{"start_seconds":99,"end_seconds":147,"summary":"Learn to always look for an overall greatest common factor before performing factoring by grouping.","sub_skills":[{"id":"EE.3","evidence":"The segment teaches how to factor a polynomial by first pulling out a GCF and then grouping."}],"clusters":[{"id":"CL.0038","evidence":"The instructor groups the terms into pairs to factor them."},{"id":"CL.0039","evidence":"The instructor factors out the overall GCF of 3 and then the GCF of each group."}]}]$seg$::jsonb)
),
tv (v) AS (SELECT $seg$scl-v1.0.0$seg$::text),
tb (v) AS (SELECT $seg$segment-tags-v5 gemini 2-pass, reviewed$seg$::text),
want AS (
  SELECT f.video_id, f.segs, (SELECT jsonb_agg(jsonb_build_object(
      's', (e->>'start_seconds')::int, 'e', (e->>'end_seconds')::int, 'summary', e->>'summary',
      'sub', (SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'), '[]'::jsonb) FROM jsonb_array_elements(e->'sub_skills') x),
      'cl',  (SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'), '[]'::jsonb) FROM jsonb_array_elements(e->'clusters') x),
      'tv', tv.v, 'tb', tb.v) ORDER BY (e->>'start_seconds')::int)
    FROM jsonb_array_elements(f.segs) e) AS norm
  FROM f, tv, tb
),
have AS (
  SELECT s.video_id, jsonb_agg(jsonb_build_object(
      's', s.start_seconds, 'e', s.end_seconds, 'summary', s.summary,
      'sub', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.sub_skill_id, 'evidence', t.evidence)
                                        ORDER BY t.sub_skill_id), '[]'::jsonb)
              FROM public.video_segment_sub_skills t WHERE t.segment_id = s.segment_id),
      'cl',  (SELECT coalesce(jsonb_agg(jsonb_build_object('id', t.cluster_id, 'evidence', t.evidence)
                                        ORDER BY t.cluster_id), '[]'::jsonb)
              FROM public.video_segment_clusters t WHERE t.segment_id = s.segment_id),
      'tv', s.taxonomy_version, 'tb', s.tagged_by) ORDER BY s.start_seconds) AS norm
  FROM public.video_segments s
  WHERE s.video_id = ANY (ARRAY['0zWTP9idFjo', '1MwEkA24_nw', '1aAtiMaWuyA', '1oFYX08ieVE', '2WRE7JH8Seg', '2sP9rnTxbow', '2u6I92--WYI', '3meaWZedEKA', '545R4urlf2A', '8A56N7Aw-nQ', '8zsxS31toRQ', 'A9jVVqRNOqM', 'Atfn3Q2cZSY', 'Bw2a469ryJs', 'D9y4Z9h0rkg', 'Fkr0CyTuKaA', 'Gz6oJJAZye4', 'HEdGb53NTv0', 'IE9rnTbTcbk', 'IYQnpSr7fXU', 'JnMT_AMnErs', 'JpB_Ta-ZEU0', 'K3IXKk2Zkuo', 'KP9pMDz0qhg', 'KT7hmSP74Xk', 'NEd-CEh3U7Y', 'P6fkZwGTAhA', 'PnjaHIiVqhk', 'Q6hqewtU_2E', 'RIFnvo8xh4E', 'ThBK41nv-I0', 'VSusHQopnjU', 'YC0u8YT8VH0', '_RilZ6zFwxI', 'aDhs2BXFQUk', 'aH-_4K3Vl9Q', 'aK-fFtOGal0', 'dWX3dyT9bTg', 'ef0ImLTUdcQ', 'fW7dfJ7_PkE', 'gFj6FUmL6No', 'gPZU0umlRMc', 'h5lPix4A1Iw', 'iKc31gO-it4', 'io50FjMFy2A', 'jFhJ4nQ-YME', 'jSRkQBhOwl8', 'jZhjQ3g63kg', 'jqqZqMRzrsY', 'lWth7s-y1mY', 'lX6PHDbk8KQ', 'mJlPNOswHN4', 'o1RgjrbhLwA', 'oD8ocr2Q5A4', 'oGVdxN0STJo', 'oXnV75ybjRU', 'pj4nCppTeZw', 'pueKfLSw-xw', 'qB1O6TlEkQU', 'qN9dLrXLTk8', 'qRjL4o77y08', 'rEfEtStTJiA', 'rFzMMg1oZO8', 'rRHhfjxRImY', 'rVC9Dy6Cgn4', 'rVuc8OGelUs', 'rYBAIbGVDVg', 'sfddPwRkLrg', 'synCZPyaMDY', 'tGQz6D-D4os', 'wkLGsN6zeK8', 'x16CyJHMdno', 'yNgvhz7fQh4', 'yTtNjEEoOH8', 'z2Lpcp2enXY']::text[])
  GROUP BY s.video_id
)
SELECT w.video_id, cardinality(public.video_segments_set(w.video_id, tv.v, tb.v, w.segs)) AS segments_set
FROM want w LEFT JOIN have h USING (video_id), tv, tb
WHERE h.norm IS DISTINCT FROM w.norm
ORDER BY w.video_id;

